import React from 'react';
import { Link } from 'react-router-dom';

const NotFound = () => {
  return (
    <div className="min-h-[60vh] flex flex-col items-center justify-center px-4 py-16">
      <div className="text-center max-w-md">
        <h1 className="text-9xl font-serif font-bold text-gold-600 mb-4">404</h1>
        <h2 className="text-3xl font-medium mb-6">Страница не найдена</h2>
        <p className="text-gray-600 mb-8 text-lg">
          К сожалению, страница, которую вы ищете, не существует или была перемещена.
        </p>
        
        <div className="flex flex-col sm:flex-row gap-4 justify-center">
          <Link 
            to="/" 
            className="bg-gold-600 hover:bg-gold-700 text-white px-6 py-3 rounded-lg font-medium transition-colors"
          >
            На главную
          </Link>
          <Link 
            to="/catalog" 
            className="bg-white hover:bg-gray-50 text-gold-600 border border-gold-600 px-6 py-3 rounded-lg font-medium transition-colors"
          >
            В каталог
          </Link>
        </div>
      </div>
    </div>
  );
};

export default NotFound;
